// FindSet opens a result set matching current filters (BC/NAV style)
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *ThemeAssetBase) FindSet() bool {
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	tableName := ThemeAssetTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT theme_code, name, content_type, size, width, height, sha256, data FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.db.Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Theme_Asset: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record in the result set (BC/NAV style)
// Must be called after FindSet() or FindSetBuffered()
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (only with FindSetBuffered)
//   - Next(-3): Skip backward 3 records (only with FindSetBuffered)
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *ThemeAssetBase) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var theme_codeNull sql.NullString
		var nameNull sql.NullString
		var content_typeNull sql.NullString
		var sha256Null sql.NullString

		err := t.currentRows.Scan(
			&theme_codeNull,
			&nameNull,
			&content_typeNull,
			&t.Size,
			&t.Width,
			&t.Height,
			&sha256Null,
			&t.Data,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Theme_Asset record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.Theme_code = types.NewCode(theme_codeNull.String)
		t.Name = types.NewCode(nameNull.String)
		t.Content_type = types.NewText(content_typeNull.String)
		t.Sha256 = types.NewText(sha256Null.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No active recordset
	return false
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation (BC/NAV style)
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *ThemeAssetBase) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := ThemeAssetTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT theme_code, name, content_type, size, width, height, sha256, data FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.db.Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for Theme_Asset: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &ThemeAssetBase{}
		record.db = t.db
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var theme_codeNull sql.NullString
		var nameNull sql.NullString
		var content_typeNull sql.NullString
		var sha256Null sql.NullString

		err := rows.Scan(
			&theme_codeNull,
			&nameNull,
			&content_typeNull,
			&record.Size,
			&record.Width,
			&record.Height,
			&sha256Null,
			&record.Data,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Theme_Asset record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.Theme_code = types.NewCode(theme_codeNull.String)
		record.Name = types.NewCode(nameNull.String)
		record.Content_type = types.NewText(content_typeNull.String)
		record.Sha256 = types.NewText(sha256Null.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate Theme_Asset records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *ThemeAssetBase) copyFromBuffered(record *ThemeAssetBase) {
	t.Theme_code = record.Theme_code
	t.Name = record.Name
	t.Content_type = record.Content_type
	t.Size = record.Size
	t.Width = record.Width
	t.Height = record.Height
	t.Sha256 = record.Sha256
	t.Data = record.Data
	t.StoreOldValues()
}

